```import {
  ensureString,
  main,
} from "<https://deno.land/x/denops_std@v0.10/mod.ts>";

main(async ({ vim }) =&gt; {
  vim.register({
    async hoge(text: unknown): Promise&lt;unknown&gt; {
      ensureString(text);
      return Promise.resolve(Array.from(text).reverse().join(""));
    },
  });

  await vim.execute(`
    command! HelloWorld echo denops#request("${vim.name}", "hoge", ["hoge"])
  `);
});```

```import { main } from "<https://deno.land/x/denops_std@v0.10/mod.ts>";

main(async ({ vim }) =&gt; {
  vim.register({
    async hoge(where: unknown): Promise&lt;unknown&gt; {
      return Promise.resolve("hoge");
    },
  });

  await vim.execute(`
    command! HelloWorld echo denops#request("${vim.name}", "hoge", [])
  `);
});```
